import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String input = br.readLine();if (input == null) return;StringBuilder sb = new StringBuilder();String vowels = "aoyeui";for (int i = 0; i < input.length(); i++) {char c = Character.toLowerCase(input.charAt(i));if (vowels.indexOf(c) == -1) {sb.append('.').append(c);}}System.out.println(sb.toString());}}